 40→export function readDriftReport():
 41→  | { report: DriftReport; raw: string }
 42→  | { error: string } {
 43→  if (!existsSync(DRIFT_REPORT_PATH)) {
 44→    return {
 45→      error: `Expected structured drift report at ${DRIFT_REPORT_PATH}.`,
 46→    };
 47→  }
 48→
 49→  try {
 50→    const raw = readFileSync(DRIFT_REPORT_PATH, "utf8");
 51→    return {
 52→      report: JSON.parse(raw) as DriftReport,
 53→      raw,
 54→    };
 55→  } catch (error) {
 56→    return {
 57→      error:
 58→        error instanceof Error
 59→          ? `Could not parse ${DRIFT_REPORT_PATH}: ${error.message}`
 60→          : `Could not parse ${DRIFT_REPORT_PATH}.`,
 61→    };
 62→  }
 63→}
