 98→export function findReconciliationEntrypoint():
 99→  | { path: string; runtime: "python3" | "bash" | "node" }
100→  | null {
101→  for (const candidate of ENTRYPOINT_CANDIDATES) {
102→    if (!existsSync(candidate)) {
103→      continue;
104→    }
105→    if (candidate.endsWith(".py")) {
106→      return { path: candidate, runtime: "python3" };
107→    }
108→    if (candidate.endsWith(".sh")) {
109→      return { path: candidate, runtime: "bash" };
110→    }
111→    return { path: candidate, runtime: "node" };
112→  }
113→  return null;
114→}
