116→export function readEntrypointSource(): { path: string; content: string } | null {
117→  const entrypoint = findReconciliationEntrypoint();
118→  if (!entrypoint) {
119→    return null;
120→  }
121→  return {
122→    path: entrypoint.path,
123→    content: readFileSync(entrypoint.path, "utf8"),
124→  };
125→}
