127→export function runReconciliationCommand(options?: {
128→  args?: string[];
129→  env?: Record<string, string>;
130→  reportPath?: string;
131→  timeoutMs?: number;
132→}) {
133→  const entrypoint = findReconciliationEntrypoint();
134→  if (!entrypoint) {
135→    return {
136→      error:
137→        "Expected a reusable reconciliation entrypoint under /workspace/scripts or /workspace/bin.",
138→    };
139→  }
140→
141→  const reportPath = options?.reportPath ?? createTempReportPath();
142→  mkdirSync(join(WORKSPACE_ROOT, "artifacts"), { recursive: true });
143→  mkdirSync(join(tmpdir(), "dec-bench-reconciliation"), { recursive: true });
144→
145→  const child = spawnSync(
146→    entrypoint.runtime,
147→    [entrypoint.path, "--report-path", reportPath, ...(options?.args ?? [])],
148→    {
149→      cwd: WORKSPACE_ROOT,
150→      encoding: "utf8",
151→      timeout: options?.timeoutMs ?? 10_000,
152→      env: {
153→        ...process.env,
154→        ...options?.env,
155→      },
156→    },
157→  );
158→
159→  return {
160→    path: entrypoint.path,
161→    reportPath,
162→    status: child.status,
163→    stdout: child.stdout ?? "",
164→    stderr: child.stderr ?? "",
165→    timedOut: child.signal === "SIGTERM" || child.signal === "SIGKILL",
166→    error: child.error?.message,
167→  };
168→}
