 10→export async function structured_drift_report_exists(
 11→  _ctx: AssertionContext,
 12→): Promise<AssertionResult> {
 13→  const reportResult = readDriftReport();
 14→  if ("error" in reportResult) {
 15→    return {
 16→      passed: false,
 17→      message: reportResult.error,
 18→      details: { expectedPath: DRIFT_REPORT_PATH },
 19→    };
 20→  }
 21→
 22→  const { report } = reportResult;
 23→  const hasCoreFields =
 24→    typeof report.pg_count === "number" &&
 25→    typeof report.topic_count === "number" &&
 26→    typeof report.ch_count === "number" &&
 27→    typeof report.tolerance === "number" &&
 28→    typeof report.status === "string" &&
 29→    Array.isArray(report.behind_systems) &&
 30→    Array.isArray(report.discrepancies);
 31→
 32→  return {
 33→    passed: hasCoreFields,
 34→    message: hasCoreFields
 35→      ? `Structured drift report found at ${DRIFT_REPORT_PATH}.`
 36→      : "Structured drift report is missing one or more required fields.",
 37→    details: {
 38→      expectedPath: DRIFT_REPORT_PATH,
 39→      presentKeys: Object.keys(report),
 40→    },
 41→  };
