 79→export async function discrepancy_context_is_actionable(
 80→  ctx: AssertionContext,
 81→): Promise<AssertionResult> {
 82→  const reportResult = readDriftReport();
 83→  if ("error" in reportResult) {
 84→    return {
 85→      passed: false,
 86→      message: reportResult.error,
 87→      details: { expectedPath: DRIFT_REPORT_PATH },
 88→    };
 89→  }
 90→
 91→  const counts = await getLiveCounts(ctx);
 92→  const behindSystems = expectedBehindSystems(counts);
 93→  const report = reportResult.report;
 94→  const discrepancies = Array.isArray(report.discrepancies) ? report.discrepancies : [];
 95→  const reportBehindSystems = Array.isArray(report.behind_systems)
 96→    ? report.behind_systems.map((value) => String(value).toLowerCase()).sort()
 97→    : [];
 98→  const expectedSystems = behindSystems.slice().sort();
 99→  const discrepancyShapeValid = discrepancies.every((entry) => {
100→    return (
101→      typeof entry?.system === "string" &&
102→      typeof entry?.expected === "number" &&
103→      typeof entry?.actual === "number" &&
104→      typeof entry?.difference === "number"
105→    );
106→  });
107→  const discrepancyCoverageValid =
108→    expectedSystems.length === 0 ? true : discrepancies.length >= expectedSystems.length;
109→  const behindSystemsValid =
110→    reportBehindSystems.length === expectedSystems.length &&
111→    reportBehindSystems.every((value, index) => value === expectedSystems[index]);
112→
113→  const passed = discrepancyShapeValid && discrepancyCoverageValid && behindSystemsValid;
114→  return {
115→    passed,
116→    message: passed
117→      ? "Drift report includes actionable discrepancy context for the current system state."
118→      : "Drift report is missing actionable discrepancy context or behind-system annotations.",
119→    details: {
120→      expectedBehindSystems: expectedSystems,
121→      reportedBehindSystems: reportBehindSystems,
122→      discrepancies,
123→    },
124→  };
125→}
